def validate_payload_discard(original, discard):
    """Prove an explicit construction-field set has no reachable consumer."""
    names=tuple(sorted(set(discard)))
    if not names or any(not name.startswith(('_','st_cq_','st_cj_')) or
                        any(char in name for char in '*?[]') for name in names):
        raise ValueError('Require explicit construction attribute names')
    pending=[original];seen=set();read=set()
    while pending:
        tree=pending.pop()
        if tree.as_pointer() in seen:continue
        seen.add(tree.as_pointer())
        for node in tree.nodes:
            if node.type=='GROUP' and node.node_tree:pending.append(node.node_tree)
            if node.bl_idname=='GeometryNodeInputNamedAttribute':
                if node.inputs['Name'].is_linked:
                    raise ValueError('Dynamic attribute names prevent an intake cleanup proof')
                read.add(node.inputs['Name'].default_value)
    pending=[m.node_tree for m in bpy.data.materials if m.node_tree];seen=set()
    while pending:
        tree=pending.pop()
        if tree.as_pointer() in seen:continue
        seen.add(tree.as_pointer())
        for node in tree.nodes:
            if node.type=='GROUP' and node.node_tree:pending.append(node.node_tree)
            field={'ShaderNodeAttribute':'attribute_name','ShaderNodeUVMap':'uv_map',
                   'ShaderNodeVertexColor':'layer_name'}.get(node.bl_idname)
            if field:read.add(getattr(node,field))
    if set(names)&read:raise ValueError('Cannot remove consumed attributes: '+str(sorted(set(names)&read)))
    return names


def assembly_payload_candidate(original, discard=ASSEMBLY_CONSTRUCTION_FIELDS):
    """Opt in GN cleanup at assembly intake, preserving live provider outputs.

    Fields are an explicit construction-workspace contract. Reject any name
    read by a reachable assembly group or material. Dynamic names prevent this
    proof and therefore reject the candidate. This function builds once; all
    later source editing and cleanup evaluate natively in Geometry Nodes.
    """
    names=validate_payload_discard(original,discard)
    calls=[n for n in original.nodes if n.type=='GROUP' and n.label=='Shared original-span construction']
    if len(calls)!=1:raise ValueError('Require the shared canonical assembly wrapper')
    for key in ('Patch Results','Strip Results'):
        if key not in calls[0].inputs or len(calls[0].inputs[key].links)!=1:
            raise ValueError('Missing linked assembly intake: '+key)
    contract=json.dumps(names)
    name=original.name+' / Assembly payload '+hashlib.sha256(contract.encode()).hexdigest()[:10]
    if name in bpy.data.node_groups:
        tree=bpy.data.node_groups[name]
        if tree.get('st_assembly_payload_discard')!=contract:raise ValueError('Payload contract name collision')
        return tree
    tree=original.copy();tree.name=name;call=tree.nodes[calls[0].name]
    for key in ('Patch Results','Strip Results'):
        socket=call.inputs[key];value=socket.links[0].from_socket
        for at,attr in enumerate(names):
            remove=tree.nodes.new('GeometryNodeRemoveAttribute')
            remove.name=remove.label=key+' / Discard construction field '+attr
            remove.inputs['Name'].default_value=attr
            remove.location=(-600-at*35,-1100-(220 if key=='Strip Results' else 0))
            tree.links.new(value,remove.inputs['Geometry']);value=remove.outputs['Geometry']
        tree.links.new(value,socket)
    tree['st_assembly_payload_discard']=contract
    return tree


def build(core,*,scoped_sources=False,apply_material=True,interpolation=False):
    """Wrap a matching kernel; opt in only with mode-aware downstream owners."""
    name=core.name+' / Canonical source inputs v2'
    if scoped_sources:name+=' / Scoped source order v1'
    if not apply_material:name+=' / Unshaded transport'
    if interpolation:name+=' / Exact or smooth v1'
    construction=name
    if len(name.encode('utf8'))>200:
        name='Prochitecture Streets / Canonical source inputs v3 / '+hashlib.sha256(construction.encode('utf8')).hexdigest()[:16]
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name);g.g.is_modifier=True
    g.g['st_construction_label']=construction
    inputs=[s for s in core.interface.items_tree if s.item_type=='SOCKET' and s.in_out=='INPUT']
    outputs=[s for s in core.interface.items_tree if s.item_type=='SOCKET' and s.in_out=='OUTPUT']
    assert any(s.name=='Sources' and s.socket_type=='NodeSocketGeometry' for s in inputs)
    g.socket('Geometry','NodeSocketGeometry')
    g.socket('Source Objects','NodeSocketCollection');g.socket('Source Binding','NodeSocketObject')
    if scoped_sources:g.socket('Source Order','NodeSocketObject')
    for key in ('Source Vertex Count','Source Edge Count'):g.socket(key,'NodeSocketInt')
    g.socket('Metres to Blender Units','NodeSocketFloat',default=1.)
    g.socket('Mesh Resolution','NodeSocketInt',default=1)
    g.socket('Pavement','NodeSocketMaterial')
    for socket in inputs:
        if socket.name=='Sources':continue
        kind=('NodeSocketCollection' if socket.name in ('Patch Results','Strip Results') else 'NodeSocketObject') if socket.socket_type=='NodeSocketGeometry' else socket.socket_type
        g.socket(socket.name,kind,default=getattr(socket,'default_value',None))
    for socket in outputs:g.socket(socket.name,socket.socket_type,'OUTPUT')
    g.socket('Source Input Status','NodeSocketGeometry','OUTPUT')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    expected_order=None
    if scoped_sources:
        order=g.node('GeometryNodeObjectInfo','Expected unchanged global source identities');order.transform_space='ORIGINAL'
        g.bind(inp.outputs['Source Order'],order.inputs['Object']);expected_order=order.outputs['Geometry']
    authored,source_ok=live_input_nodes.source_geometry(g.g,inp,expected_order=expected_order)
    source_ok=c.V(g,source_ok)*g.math('GREATER_THAN',inp.outputs['Metres to Blender Units'],0.)
    info=g.node('GeometryNodeObjectInfo');info.transform_space='ORIGINAL'
    g.bind(inp.outputs['Source Binding'],info.inputs['Object'])
    view=g.node('GeometryNodeGroup','Live canonical Section endpoints and original Street views')
    view.node_tree=curved_port_source_nodes.build(allow_exact=interpolation)
    for key,value in (('Sources',authored),('Binding',info.outputs['Geometry']),('Input Valid',source_ok)):
        g.bind(value,view.inputs[key])
    call=g.node('GeometryNodeGroup','Shared original-span construction');call.node_tree=core
    for socket in inputs:
        if socket.name=='Sources':value=view.outputs['Geometry']
        elif socket.name in ('Patch Results','Strip Results'):
            providers=g.node('GeometryNodeCollectionInfo','Independently evaluated patch owners');providers.transform_space='RELATIVE'
            providers.inputs['Separate Children'].default_value=True
            g.bind(inp.outputs[socket.name],providers.inputs['Collection'])
            realize=g.node('GeometryNodeRealizeInstances');g.bind(providers.outputs['Instances'],realize.inputs['Geometry'])
            normalize=g.node('GeometryNodeTransform','Cached patch coordinates in metres')
            g.bind(realize.outputs['Geometry'],normalize.inputs['Geometry'])
            g.bind(g.math('DIVIDE',1.,inp.outputs['Metres to Blender Units']),normalize.inputs['Scale'])
            value=normalize.outputs['Geometry']
        elif socket.socket_type=='NodeSocketGeometry':
            table=g.node('GeometryNodeObjectInfo',socket.name+' private topology');table.transform_space='ORIGINAL'
            g.bind(inp.outputs[socket.name],table.inputs['Object']);value=table.outputs['Geometry']
        elif socket.name=='Cell Size':
            resolution=g.math('MINIMUM',g.math('MAXIMUM',inp.outputs['Mesh Resolution'],1.),4.)
            value=g.math('DIVIDE',inp.outputs['Cell Size'],g.math('POWER',2.,resolution-1.))
        else:value=inp.outputs[socket.name]
        g.bind(value,call.inputs[socket.name])
    valid=c.V(g,call.outputs['Valid'])*c.V(g,view.outputs['Valid'])
    drawable=(c.V(g,call.outputs['Output Valid'])*c.V(g,view.outputs['Valid'])
              if 'Output Valid' in call.outputs else valid)
    failure_records=None
    if 'Output Valid' in call.outputs and 'Failure Records' in call.outputs:
        source_error=c._line(g,1)
        topology_error=(1.-c.V(g,view.outputs['Topology Valid']))*g.math('GREATER_THAN',inp.outputs['Metres to Blender Units'],0.)
        code=c.choose(g,topology_error,9,30,'INT')
        for key,value in (('st_diagnostic_code',code),('st_section_id',-1),
                          ('st_intersection_id',-1),('st_bundle_id',-1),
                          ('st_cn_kind',-1),('st_cn_owner',-1)):
            source_error=c._store(g,source_error,key,value,'INT')
        failure_records=c.choose(g,view.outputs['Valid'],call.outputs['Failure Records'],source_error,'GEOMETRY')
    for socket in outputs:
        value=call.outputs[socket.name]
        if socket.name=='Valid':value=valid
        elif socket.name=='Output Valid':value=drawable
        elif socket.name=='Failure Records' and failure_records is not None:value=failure_records
        elif socket.name=='Geometry':
            if failure_records is None:
                value=boundary._empty(g,value,drawable)
            else:
                components=g.node('GeometryNodeSeparateComponents','Surface acceptance is independent of diagnostic visibility')
                g.bind(value,components.inputs['Geometry'])
                points=g.node('GeometryNodeMeshToPoints','Keep failure explanations when no pavement survives')
                points.mode='VERTICES';g.bind(failure_records,points.inputs['Mesh'])
                value=boundary._join(g,boundary._empty(g,components.outputs['Mesh'],drawable),points.outputs['Points'])
            if apply_material:
                material=g.node('GeometryNodeSetMaterial','Carriageway pavement')
                g.bind(value,material.inputs['Geometry']);g.bind(inp.outputs['Pavement'],material.inputs['Material'])
                if any(s.name=='Separators' for s in inputs):
                    g.bind(g.math('LESS_THAN',c.named(g,'st_separator_closure','BOOLEAN'),.5),material.inputs['Selection'])
                value=material.outputs['Geometry']
